    self._log_time(predict_1_time_full, predict_1_batch_size, full=True)


def _log_time(self, time_value, batch_size, full=False):
    time_unit = 's'
    if round(time_value, 2) == 0:
        time_unit = 'ms'
        time_value = time_value * 1000
    if full:
        logger.log(20, f'\t{round(time_value, 3)}{time_unit}\t = Validation runtime (1 row | {batch_size} batch size | FULL)')
    else:
        logger.log(20, f'\t{round(time_value, 3)}{time_unit}\t = Validation runtime (1 row | {batch_size} batch size)')
